// Built-in defaults used by `--render-snapshot` (and by tests) when no
// configure.json is given. They mirror packages/contracts (design-tokens.json,
// actions.ts labels/icons/batch, menus.ts orders, formats.ts extensions);
// ContractDriftTests compares them with the TypeScript sources and with a
// configure message generated by scripts/gen-fixtures.mjs from the real
// `buildHelperMenus`. In the running helper, main's `configure` always wins.

public enum ThemeName: String, CaseIterable, Sendable {
  case light, dark, highContrast
}

public enum DefaultConfig {
  public struct ActionInfo: Sendable {
    public let label: (ko: String, en: String)
    public let icon: IconId?
    public let batch: Bool
  }

  /// ACTIONS[...].wheelLabel / icon / batch.
  public static func action(_ id: ActionId) -> ActionInfo {
    func fmt(_ label: String) -> ActionInfo { ActionInfo(label: (label, label), icon: nil, batch: true) }
    switch id {
    case .convertJpeg: return fmt("JPG")
    case .convertPng: return fmt("PNG")
    case .convertWebp: return fmt("WEBP")
    case .convertHeic: return fmt("HEIC")
    case .convertTiff: return fmt("TIFF")
    case .convertAvif: return fmt("AVIF")
    case .convertBmp: return fmt("BMP")
    case .convertPdf: return fmt("PDF")
    case .convertDocx: return fmt("DOCX")
    case .convertTxt: return fmt("TXT")
    case .toolCompress: return ActionInfo(label: ("압축", "COMPRESS"), icon: .compress, batch: true)
    case .toolMetadata: return ActionInfo(label: ("메타데이터", "METADATA"), icon: .metadata, batch: true)
    case .toolEdit: return ActionInfo(label: ("편집", "EDIT"), icon: .edit, batch: false)
    case .toolAnnotate: return ActionInfo(label: ("주석", "ANNOTATE"), icon: .annotate, batch: false)
    case .toolAddBackground: return ActionInfo(label: ("배경 추가", "ADD BG"), icon: .background, batch: false)
    case .toolCrop: return ActionInfo(label: ("자르기", "CROP"), icon: .crop, batch: false)
    case .toolRedact: return ActionInfo(label: ("가리기", "REDACT"), icon: .redact, batch: false)
    }
  }

  /// Which inputs an action accepts (ACTIONS[...].inputs): "image", "pdf".
  public static func inputs(_ id: ActionId) -> Set<String> {
    switch id {
    case .convertJpeg, .convertPng, .convertDocx: return ["image", "pdf"]
    case .convertTxt: return ["pdf"]
    default: return ["image"]
    }
  }

  public static let pdfConvertOrder: [ActionId] = [.convertDocx, .convertJpeg, .convertPng, .convertTxt]
  public static let imageConvertOrder: [ActionId] = [
    .convertJpeg, .convertPng, .convertWebp, .convertHeic, .convertTiff, .convertAvif, .convertBmp, .convertPdf, .convertDocx,
  ]
  public static let imageToolsOrder: [ActionId] = [
    .toolCompress, .toolMetadata, .toolEdit, .toolAnnotate, .toolAddBackground, .toolCrop, .toolRedact,
  ]

  /// `baseMenuOrder(key, mode)` from menus.ts.
  public static func baseMenuOrder(_ key: MenuKey, _ mode: WheelMode) -> [ActionId] {
    switch key {
    case .pdf:
      return mode == .convert ? pdfConvertOrder : []
    case .mixed:
      return mode == .convert ? pdfConvertOrder.filter { inputs($0).isSuperset(of: ["image", "pdf"]) } : []
    case .images:
      return mode == .tools ? imageToolsOrder : imageConvertOrder
    case .image(let own):
      if mode == .tools { return imageToolsOrder }
      return imageConvertOrder.filter { $0.rawValue != "convert.\(own.rawValue)" }
    }
  }

  /// Demo capability for snapshots: everything enabled except HEIC encoding
  /// (the measured state of the bundled sharp build), so the disabled style shows.
  public static func demoDisabledReason(_ id: ActionId, locale: HelperLocale) -> String? {
    guard id == .convertHeic else { return nil }
    return locale == .ko ? "HEIC 인코더가 이 빌드에 없음" : "No HEIC encoder in this build"
  }

  public static func menus(locale: HelperLocale) -> [HelperMenu] {
    MenuKey.allCases.map { key in
      func sectors(_ mode: WheelMode) -> [WheelSector] {
        baseMenuOrder(key, mode).map { id in
          let info = action(id)
          let reason = demoDisabledReason(id, locale: locale)
          return WheelSector(
            actionId: id, label: locale == .ko ? info.label.ko : info.label.en, icon: info.icon,
            enabled: reason == nil, reason: reason, batch: info.batch
          )
        }
      }
      return HelperMenu(key: key, convert: sectors(.convert), tools: sectors(.tools))
    }
  }

  /// FORMAT_INFO input extensions for every image format and PDF.
  public static let extensions: [String: MenuKey] = {
    var map: [String: MenuKey] = [:]
    let table: [(ImageFormat, [String])] = [
      (.jpeg, [".jpg", ".jpeg", ".jpe", ".jfif"]), (.png, [".png"]), (.webp, [".webp"]), (.gif, [".gif"]),
      (.tiff, [".tif", ".tiff"]), (.avif, [".avif"]), (.heic, [".heic", ".heif", ".hif"]), (.bmp, [".bmp", ".dib"]),
    ]
    for (format, exts) in table {
      for ext in exts { map[ext] = .image(format) }
    }
    map[".pdf"] = .pdf
    return map
  }()

  public static func strings(locale: HelperLocale) -> HelperStrings {
    switch locale {
    case .ko:
      return HelperStrings(
        dropHint: "여기에 놓기", unsupported: "지원하지 않는 파일", multiFileUnsupported: "한 번에 한 파일만", fileCount: "{n}개 파일",
        unsupportedFolder: "폴더는 지원하지 않음", unsupportedNonFile: "파일이 아닌 항목", unsupportedVirtual: "디스크에 없는 항목",
        unsupportedCloud: "먼저 내려받으세요"
      )
    case .en:
      return HelperStrings(
        dropHint: "Drop here", unsupported: "Not supported", multiFileUnsupported: "One file at a time", fileCount: "{n} files",
        unsupportedFolder: "Folders aren't supported", unsupportedNonFile: "Not a file", unsupportedVirtual: "Not a file on disk",
        unsupportedCloud: "Download it first"
      )
    }
  }

  /// `wheelTokens(theme, reduceMotion)` from packages/contracts/src/tokens.ts with design-tokens.json values.
  public static func tokens(theme: ThemeName, reduceMotion: Bool) -> WheelTokens {
    func c(_ hex: String) -> RGBA { RGBA(hex: hex)! }
    let palette: [String: String]
    switch theme {
    case .light:
      palette = [
        "wheelDisc": "#FFF3E6B8", "wheelRing": "#FFFFFFD9", "wheelShadow": "#7A2E0040", "sector": "#FCE4CCF2",
        "sectorHover": "#FFD9B8F7", "sectorText": "#3B2A1E", "sectorIcon": "#4A3426", "sectorDisabled": "#F1E5DAD9",
        "sectorDisabledText": "#A8978A", "sectorActive": "#D4441C", "sectorActiveText": "#FFFFFF", "capsule": "#F7B98AF2",
        "capsuleText": "#3B2A1E", "capsuleReject": "#E9D9CCF2",
      ]
    case .dark:
      palette = [
        "wheelDisc": "#2C211BCC", "wheelRing": "#FFFFFF59", "wheelShadow": "#00000066", "sector": "#4A372BF2",
        "sectorHover": "#5C4434F7", "sectorText": "#FCE8D8", "sectorIcon": "#FCE8D8", "sectorDisabled": "#3A2E27D9",
        "sectorDisabledText": "#8C7A6D", "sectorActive": "#FF6A3D", "sectorActiveText": "#1E120B", "capsule": "#7A4A2EF2",
        "capsuleText": "#FFF1E6", "capsuleReject": "#3A2E27F2",
      ]
    case .highContrast:
      palette = [
        "wheelDisc": "#FFFFFFFF", "wheelRing": "#000000FF", "wheelShadow": "#00000000", "sector": "#FFFFFFFF",
        "sectorHover": "#FFE7D6FF", "sectorText": "#000000", "sectorIcon": "#000000", "sectorDisabled": "#E6E6E6FF",
        "sectorDisabledText": "#595959", "sectorActive": "#B33000", "sectorActiveText": "#FFFFFF", "capsule": "#000000FF",
        "capsuleText": "#FFFFFF", "capsuleReject": "#595959FF",
      ]
    }
    return WheelTokens(
      wheelDisc: c(palette["wheelDisc"]!), wheelRing: c(palette["wheelRing"]!), wheelShadow: c(palette["wheelShadow"]!),
      sector: c(palette["sector"]!), sectorHover: c(palette["sectorHover"]!), sectorText: c(palette["sectorText"]!),
      sectorIcon: c(palette["sectorIcon"]!), sectorDisabled: c(palette["sectorDisabled"]!),
      sectorDisabledText: c(palette["sectorDisabledText"]!), sectorActive: c(palette["sectorActive"]!),
      sectorActiveText: c(palette["sectorActiveText"]!), capsule: c(palette["capsule"]!), capsuleText: c(palette["capsuleText"]!),
      capsuleReject: c(palette["capsuleReject"]!),
      labelSize: 15, labelWeight: 700, iconSize: 20, capsuleTextSize: 16,
      appearMs: reduceMotion ? 0 : 140, disappearMs: reduceMotion ? 0 : 90
    )
  }

  /// Hex strings of a theme (for drift tests against design-tokens.json).
  public static func paletteHex(theme: ThemeName) -> [String: String] {
    let t = tokens(theme: theme, reduceMotion: false)
    var result: [String: String] = [:]
    for field in WheelTokens.colorFields {
      result[field.name] = hex(t[keyPath: field.keyPath])
    }
    return result
  }

  static func hex(_ color: RGBA) -> String {
    func byte(_ v: Double) -> String {
      let n = Int((v * 255).rounded())
      let digits = Array("0123456789ABCDEF")
      return String([digits[n / 16], digits[n % 16]])
    }
    return "#" + byte(color.r) + byte(color.g) + byte(color.b) + (color.a < 1 ? byte(color.a) : "")
  }

  public static func config(locale: HelperLocale = .ko, theme: ThemeName = .light, enabled: Bool = true, reduceMotion: Bool = false) -> HelperConfig {
    HelperConfig(
      enabled: enabled,
      locale: locale,
      geometry: .default,
      tokens: tokens(theme: theme, reduceMotion: reduceMotion),
      reduceMotion: reduceMotion,
      highContrast: theme == .highContrast,
      convertModifiers: ModifierCombo([.shift]),
      toolsModifiers: ModifierCombo([.alt, .shift]),
      extensions: extensions,
      menus: menus(locale: locale),
      strings: strings(locale: locale)
    )
  }
}
